import java.util.*;

class Solution {
  public boolean[] canMakePalindromeQueries(String s, int[][] queries) {
    int n = s.length() / 2;
    String a = s.substring(0, n), b = new StringBuilder(s.substring(n)).reverse().toString();
    int[][] x = new int[n + 1][26], y = new int[n + 1][26];
    for (int i = 1; i <= n; i++) {
      x[i] = x[i - 1].clone();
      y[i] = y[i - 1].clone();
      x[i][a.charAt(i - 1) - 'a']++;
      y[i][b.charAt(i - 1) - 'a']++;
    }
    int[] bad = new int[n + 1];
    for (int i = 1; i <= n; i++) bad[i] = bad[i - 1] + (a.charAt(i - 1) == b.charAt(i - 1) ? 0 : 1);
    boolean[] r = new boolean[queries.length];
    for (int z = 0; z < queries.length; z++) {
      int[] q = queries[z];
      int l = q[0], h = q[1], u = q[2] - n, v = q[3] - n;
      u = n - 1 - u;
      v = n - 1 - v;
      int t = u;
      u = v;
      v = t;
      r[z] = l <= u ? check(l, h, u, v, x, y, bad) : check(u, v, l, h, y, x, bad);
    }
    return r;
  }

  private boolean check(int a, int b, int c, int d, int[][] x, int[][] y, int[] w) {
    int n = w.length - 1;
    if (w[a] > 0 || w[n] - w[Math.max(b, d) + 1] > 0) return false;
    if (b >= d) return Arrays.equals(seg(x, a, b), seg(y, a, b));
    if (b < c)
      return w[c] - w[b + 1] == 0
          && Arrays.equals(seg(x, a, b), seg(y, a, b))
          && Arrays.equals(seg(x, c, d), seg(y, c, d));
    int[] p = sub(seg(x, a, b), seg(y, a, c - 1)), q = sub(seg(y, c, d), seg(x, b + 1, d));
    return p != null && q != null && Arrays.equals(p, q);
  }

  private int[] seg(int[][] p, int l, int r) {
    int[] z = new int[26];
    for (int i = 0; i < 26; i++) z[i] = p[r + 1][i] - p[l][i];
    return z;
  }

  private int[] sub(int[] a, int[] b) {
    int[] z = new int[26];
    for (int i = 0; i < 26; i++) {
      z[i] = a[i] - b[i];
      if (z[i] < 0) return null;
    }
    return z;
  }
}
